            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(bid)

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, 20.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    total_agents = 1 + len(alive)
    tight_supply = supply <= WATER_REQ * 1.25
    very_tight = supply < WATER_REQ * 1.05
    enough_for_two = supply >= WATER_REQ * 2

    danger = 0
    if hp <= 3:
        danger += 3
    elif hp <= 5:
        danger += 2
    elif hp <= 7:
        danger += 1
    if no_water_days >= 2:
        danger += 3
    elif no_water_days >= 1:
        danger += 1
    if very_tight:
        danger += 2
    elif tight_supply:
        danger += 1
    if day >= 8:
        danger += 1

    if highest_prev >= 170:
        pressure = 'extreme'
    elif highest_prev >= 135:
        pressure = 'high'
    elif highest_prev >= 90:
        pressure = 'medium'
    else:
        pressure = 'low'

    if danger >= 5:
        target = highest_prev + 2.5 if highest_prev > 0 else 150.0
    elif danger >= 3:
        if pressure == 'extreme':
            target = highest_prev + 1.0
        elif pressure == 'high':
            target = highest_prev + 2.0
        else:
            target = max(95.0, avg_prev + 8.0)
    else:
        if pressure == 'extreme':
            target = 18.0 if hp >= 7 and no_water_days == 0 else highest_prev + 1.0
        elif pressure == 'high':
            target = 28.0 if hp >= 8 and enough_for_two else 60.0
        elif pressure == 'medium':
            target = avg_prev + 3.0
        else:
            target = 45.0

