        target = min(target, budget * 0.72)
    elif budget < 200 and danger < 3:
        target = min(target, budget * 0.55)

    if day == 1 and hp >= 9 and no_water_days == 0:
        target = min(target, 55.0)

    bid = max(0.0, min(budget, target))
